 * in the workspace and in `projectId`, and must not be archived.
 */
async function requireLiveParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const found = await issueRepo.findIssueById(orgId, parentId);
  const parent = requireFound(
    found !== null && found.projectId === projectId ? found : null,
    "Issue",
    parentId,
  );
  assertNotArchived("Issue", parent.id, parent);
  return parent;
