/** Ids from `issue`'s parent up to its root; stops early on a corrupt loop. */
async function ancestorIds(orgId: OrgId, issue: Issue): Promise<IssueId[]> {
  const chain: IssueId[] = [];
  const seen = new Set<string>([issue.id]);
  let next = issue.parentId;
  while (next !== null && !seen.has(next)) {
    seen.add(next);
    const ancestor = await issueRepo.findIssueById(orgId, next);
    if (ancestor === null) break;
    chain.push(ancestor.id);
    next = ancestor.parentId;
  }
  return chain;
}

