/**
 * Places an issue under a parent of its own project, moves it to another, or
 * (with `null`) makes it a root again. Everything below it moves along, so
 * the depth check looks at where its deepest live descendant would land.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.parentId === input.parentId) return before;

  if (input.parentId !== null) {
    const parent = await requireLiveParent(
      input.orgId,
      before.projectId,
      input.parentId,
    );

    const ancestors = await ancestorIds(input.orgId, parent);
    if (parent.id === before.id || ancestors.includes(before.id)) {
      throw new IssueHierarchyError(before.id, "cycle");
    }

    const parentLevel = ancestors.length;
    const below = await issueRepo.listDescendants(input.orgId, before.id);
    const levels = new Map<string, number>([[before.id, parentLevel + 1]]);
    let deepest = parentLevel + 1;
    for (const node of below) {
      if (!isLive(node)) continue;
      const level = (levels.get(node.parentId) ?? parentLevel + 1) + 1;
      levels.set(node.id, level);
      deepest = Math.max(deepest, level);
    }
    if (deepest > MAX_SUB_ISSUE_DEPTH) {
      throw new IssueHierarchyError(before.id, "too_deep");
    }
  }

  const after = await issueRepo.setIssueParent(
    input.orgId,
    input.issueId,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

