    await issueService.changeIssueStatus(a, { orgId: o, issueId: c2.id, status: "done" });
    await issueService.changeIssueStatus(a, { orgId: o, issueId: c1.id, status: "canceled" });
    const n = await notificationRepo.listNotifications({ orgId: o, recipientId: t.userIds.admin, unreadOnly: false, limit: 50 } as any);
    console.log(n.items.map((x) => x.kind + x.body));
    const ev: string[] = [];
    const off = subscribe("issue.archived", (p) => { ev.push(p.issueId); });
    await issueService.archiveIssue(a, o, root.id);
    off();
    expect(ev).toHaveLength(4);
  });
});
